extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var grid := find_by_name(main, "DungeonGrid") as GridMap
	if not check("grid", grid != null, "Nella scena serve un nodo GridMap chiamato DungeonGrid"):
		return
	check("cell_size", grid.cell_size == Vector3(2, 2, 2), "GridMap deve avere cell_size pari a Vector3(2, 2, 2)")

	check("has_func", has_function(main, "get_dungeon_cell_item"), "main.gd deve contenere la funzione get_dungeon_cell_item(coords: Vector3i) -> int")

	var item_center = call_if_exists(main, "get_dungeon_cell_item", [Vector3i(0, -2, 0)])
	check("center_item", typeof(item_center) == TYPE_INT and item_center == 0, "get_dungeon_cell_item(Vector3i(0, -2, 0)) deve restituire l'ID 0")

	var all_set := true
	for x in range(-1, 2):
		for z in range(-1, 2):
			var val = call_if_exists(main, "get_dungeon_cell_item", [Vector3i(x, -2, z)])
			if typeof(val) != TYPE_INT or val != 0:
				all_set = false
	check("all_9_cells", all_set, "Tutte le 9 celle da x=-1..1 e z=-1..1 alla quota y=-2 devono avere blocco con ID 0")

